  "claims": [
    {
      "claim": "Pethidine/meperidine L1 and L2 records show absolute oral bioavailability of 0.80–0.87 in cirrhosis and about 0.48 in normal subjects, all above the 20% threshold.",
      "card_ids": ["C07", "C14", "C17", "C18", "C19", "C23", "C29", "C34", "C35", "C36"]
    },
    {
      "claim": "Encainide L1 and L2 records show oral bioavailability values of 0.48–1.05 across cirrhotic EM/PM patients, with L1 values of 76–78%, all above 20%.",
      "card_ids": ["C03", "C06", "C12", "C21", "C25", "C26", "C31", "C32"]
    },
    {
      "claim": "Meptazinol L1/L2 confirm 27.9 ± 5.3% in cirrhosis, but L2 notes this is a four-fold increase over controls, so this context is less transferable to a no-condition query.",
      "card_ids": ["C04", "C22", "C33"]
    },
    {
      "claim": "Thiophene/heteroaryl-containing drugs tenidap, suprofen, R406, and ziprasidone show absolute oral bioavailability of 55–92%, supporting that the query's thiophene motif is not inherently associated with low F.",
      "card_ids": ["C05", "C09", "C10", "C11", "C13", "C15", "C30"]
    },
    {
      "claim": "Other L1 records are positive (SAHA 43%, FK788 55%, PEMA at least 80%); the only low L2 value, FK788 9.6% in rats, is species-specific and not applicable to the human-oriented query.",
      "card_ids": ["C01", "C02", "C08", "C16", "C24"]
    }
  ],
  "new_evidence_assessment": [
    {
